import sys, os, json, subprocess
SD = '/srv/kb/worker/builtin_engine/scripts'
if SD not in sys.path:
    sys.path.insert(0, SD)
_kid = str(bindings.get('kid') or '').strip()
if not _kid:
    raise ValueError('缺少 kid（文档 knowledge_id）')
_kb = bindings.get('kb_id') or os.environ.get('WEKNORA_KB_ID', '')
_env = dict(os.environ)
if _kb:
    _env['WEKNORA_KB_ID'] = _kb
_env['WEKNORA_KNOWLEDGE_ID'] = _kid
_fname = str(bindings.get('source_file') or bindings.get('doc_name') or '').strip()
if _fname:
    _env['WEKNORA_DOC_NAME'] = _fname
_cmd = [sys.executable, os.path.join(SD, 'run_one.py'), _kid]
if _kb:
    _cmd += ['--kb', _kb]
if str(bindings.get('skip_final') or 'false').strip().lower() in ('true', '1'):
    _cmd += ['--skip-final']
print(f'[n3] 执行: {" ".join(_cmd)}')
_r = subprocess.run(_cmd, env=_env, capture_output=True, text=True, timeout=9000)
if _r.stdout:
    print(_r.stdout[-4000:])
if _r.returncode != 0:
    if _r.stderr:
        print('STDERR:', _r.stderr[-2000:])
    raise RuntimeError(f'索引wiki创建失败（exit {_r.returncode}）')
bindings['build_summary'] = (
    f'索引wiki创建完成: doc={_fname or _kid} chunks={bindings.get("chunk_count", 0)}'
)
print(f'[n3] {bindings["build_summary"]}')

